const SCENARIOS={
"s01":{"$schema":"../../schema/scenario.schema.json","id":"s01","slug":"s01-executive-sales-dashboard","type":"sprint","stage":"analyst","order":1,"title":"Executive sales dashboard","seo":"Power BI practice scenario: a VP of Sales needs to know why Q1 revenue growth is slowing before Monday. Messy export, vague requirements, duplicate rows and currency conversion.","summary":"The VP of Sales thinks Q1 growth is slowing and needs one slide and a dashboard for Monday's leadership meeting.","minutes":300,"skills":["power-query","modeling","dax","visuals","testing","communication"],"prereq":[],"next":"s02","ticket":{"id":"BI-1042","kind":"ticket","priority":"High","status":"Open","reporter":"jordan","opened":"Fri 10 Apr 2026, 16:52","due":"Mon 13 Apr 2026, 09:00","labels":["sales","dashboard","leadership"]},"impact":"Leadership decides on Monday whether to cut the Q2 marketing budget or push harder on wholesale. If the number on the slide is wrong in either direction, they make the wrong call, and they stop trusting the BI team.","messages":[{"from":"jordan","to":"you","via":"email","at":"Fri 10 Apr, 16:52","subject":"Q1 numbers for Monday","body":["Hi, and welcome aboard! I know it's your first week, but I need your help.","Q1 felt slower than it should have. The ops export says we sold **$274,539** in Q1, and last year's board deck had Q1 2025 at **$232,235**. That would be +18.2%, which is great, but my regional managers keep telling me March was flat or worse. Something doesn't add up.","For Monday's leadership meeting (9:00) I need to know: is Q1 revenue growth really slowing, where, and why? One slide, plus the dashboard behind it so I can answer follow-up questions.","Kenji can get you whatever data you need. Thanks! Jordan"]},{"from":"tomas","to":"jordan","via":"email","at":"Fri 10 Apr, 17:05","subject":"FW: Q1 numbers for Monday","body":["Jordan, for the record: Central had a rough March. Our biggest wholesale account went quiet in February and I haven't got a straight answer from them yet. Tomas"]},{"from":"kenji","to":"you","via":"chat","at":"Fri 10 Apr, 17:20","body":["Hey! The Q1 extract is in the shared folder (company/*.csv), same export the old dashboard used: orders, lines, returns, customers, products, regions, FX. Extracted this morning, 10 Apr.","Heads-up: the export job had a hiccup in March and we re-ran it. Should be fine 🤞. Prices are in the order currency; Europe sells in EUR."]},{"from":"elena","to":"you","via":"chat","at":"Fri 10 Apr, 17:31","body":["Before you build anything, write down what \"revenue\" means for Jordan and get Jordan to agree to it. Last time someone used gross, Finance used net, and it was a mess.","And reconcile your total back to the raw file before Monday. I'll review on Sunday evening."]}],"evidence":[{"id":"orders","kind":"file","title":"orders.csv","file":"data/experience/company/orders.csv","desc":"One row per order header: dates, customer, channel, sales region, currency, status."},{"id":"lines","kind":"file","title":"order_lines.csv","file":"data/experience/company/order_lines.csv","desc":"One row per order line (supposedly): product, quantity, unit price in the order currency, discount %."},{"id":"returns","kind":"file","title":"returns.csv","file":"data/experience/company/returns.csv","desc":"Returns up to the extract date, linked to the original order line."},{"id":"customers","kind":"file","title":"customers.csv","file":"data/experience/company/customers.csv"},{"id":"products","kind":"file","title":"products.csv","file":"data/experience/company/products.csv"},{"id":"regions","kind":"file","title":"regions.csv","file":"data/experience/company/regions.csv"},{"id":"fx","kind":"file","title":"fx_rates.csv","file":"data/experience/company/fx_rates.csv","desc":"Monthly average US dollars per euro."},{"id":"wiki","kind":"doc","title":"Sales terminology (team wiki, last edited March 2023)","body":["**Revenue**: total sales for the period.","**Net revenue**: revenue after discounts.","**Bookings**: orders placed in the period.","**Returns**: handled by Finance.","**Regions**: West, South, East, Central, Europe. Sales are credited to the region of the store or rep that made the sale."]},{"id":"deck","kind":"table","title":"Slide 4 of last year's board deck (Q1 2025)","cols":["Metric","Q1 2025","Note"],"rows":[["Revenue","$232,235","Record quarter"],["Source","Ops export","All orders"]]},{"id":"readme","kind":"doc","title":"Export job README (Kenji's team)","body":["- orders: OrderID is unique. Status is Completed or Cancelled. PostingDate is the date the ledger recognises the sale. SalesRegionKey is the selling region.\n- order_lines: (OrderID, LineNo) identifies a line. UnitPrice is in the order currency, before the line discount. DiscountPct is a whole number.\n- returns: RefundAmount is in the order currency. ShippingRefund is postage refunded to the customer.\n- fx_rates: monthly average, USD per 1 EUR."]}],"tasks":["List the questions you would ask Jordan before building anything, and the definitions you will use if nobody answers by Sunday.","Profile the export before trusting it. Write down every rule you apply (what you exclude, fix or convert, and why).","Build a small star schema in Power BI Desktop and the measures you need.","Answer the question: is growth slowing, where, and why? Quantify the main drivers.","Build one executive page and write a three-sentence summary for Jordan's slide.","Reconcile: show how you get from the raw file's total to your total, adjustment by adjustment."],"deliverables":[{"id":"req","t":"requirements.md: the questions, and the definitions Jordan agreed (or you assumed)","artifact":"requirements"},{"id":"asm","t":"assumptions.md: every assumption with its impact and who should confirm it","artifact":"assumptions"},{"id":"kpi","t":"KPI dictionary for Gross Sales, Net Sales and YoY growth","artifact":"kpi-dictionary"},{"id":"val","t":"validation.md: raw-to-model reconciliation with every adjustment","artifact":"validation-plan"},{"id":"rep","t":"The report (PBIP) with one executive page"},{"id":"sum","t":"Three-sentence executive summary for the slide"}],"hints":["Before you add anything up, count. How many rows does order_lines.csv have, and how many distinct (OrderID, LineNo) pairs? Then look at Status and at the customer list.","\"Revenue\" has at least four candidate meanings here: list price or after discount, before or after returns, and in which currency. Pick one, write it down, and compare growth month by month, not just for the quarter.","Split the year-on-year change by channel, then by customer, then by product. One customer and one product explain most of the slowdown; one new channel hides part of it."],"rubric":[{"id":"correct","n":"Technical correctness","w":30,"good":"Q1 2026 and Q1 2025 totals match the model answer within 0.5%. Duplicates, cancelled orders and the test account are excluded; euros are converted with the monthly rate."},{"id":"invest","n":"Investigation quality","w":20,"good":"Monthly trend shows where the slowdown starts. Drivers are quantified (customer, product, channel) and they add up to the change."},{"id":"req","n":"Requirements and assumptions","w":15,"good":"Questions are specific: definition, grain, currency, returns, cancelled orders, which date. Assumptions are written down with who must confirm them."},{"id":"valid","n":"Validation","w":15,"good":"A reconciliation from the raw export to the reported total, where every adjustment is named, counted and sums exactly."},{"id":"comm","n":"Communication","w":15,"good":"Three sentences Jordan can say out loud: what happened, why, and what it means for Q2. No jargon."},{"id":"design","n":"Report design","w":5,"good":"One page answers \"is growth slowing and why\" in five seconds."}],"retro":["Which of the export's problems would you have missed without counting rows first?","What would you have told Jordan on Monday if you had used the email's number?","Which of your assumptions are you least sure about, and who owns the answer?","What check would you automate so the March export problem can't happen silently again?"],"refs":[{"title":"Data profiling tools in Power Query","url":"https://learn.microsoft.com/en-us/power-query/data-profiling-tools"},{"title":"Star schema guidance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/star-schema"}]},
"s02":{"$schema":"../../schema/scenario.schema.json","id":"s02","slug":"s02-finance-disputes-revenue","type":"sprint","stage":"analyst","order":2,"title":"Finance disputes the dashboard","seo":"Power BI reconciliation exercise: the CFO says the dashboard's net revenue is too high. Reconcile against the general ledger and find every cause.","summary":"The CFO says the Q1 net revenue on your new dashboard is too high and wants it explained before the board pack goes out.","minutes":240,"skills":["dax","modeling","testing","communication","power-query"],"prereq":["s01"],"next":"s03","ticket":{"id":"BI-1057","kind":"ticket","priority":"Urgent","status":"Open","reporter":"sarah","opened":"Wed 15 Apr 2026, 08:14","due":"Fri 17 Apr 2026, 12:00","labels":["finance","reconciliation","board-pack"]},"story":"Your Q1 dashboard went to the leadership meeting on Monday and Jordan's slide was well received. On Tuesday Jordan forwarded the dashboard link to the CFO.","impact":"The board pack goes to the directors on Friday. If the board sees one revenue figure from Sales and another from Finance, the question stops being \"why is growth slowing\" and becomes \"can we trust any of our numbers\". Finance's number is the one the auditors will check.","messages":[{"from":"sarah","to":"you","via":"email","at":"Wed 15 Apr, 08:14","subject":"Q1 net revenue on the sales dashboard","body":["Good morning,","Jordan shared your Q1 dashboard with me. It shows net revenue of **$244,409** for Q1 2026. Our ledger shows **$241,663**. Your figure is **$2,746 too high**.","The board pack goes out on Friday at noon and it will show the ledger figure. Before then I need to understand exactly why the two differ, and I need the dashboard to either match the ledger or say clearly that it measures something else.","Nina will send you the ledger extract. Please don't change anything on the dashboard until we've spoken.","Sarah Chen, CFO"]},{"from":"nina","to":"you","via":"email","at":"Wed 15 Apr, 09:02","subject":"RE: Q1 net revenue on the sales dashboard","body":["Hi, attached is the Q1 GL extract for the revenue accounts, by posting period. This is what goes into the board pack.","I don't know how your dashboard is built, so I can't tell you where the difference is. I tried by month in Excel and every month is off by a different amount, so it's not one thing. Happy to jump on a call."]},{"from":"jordan","to":"you","via":"chat","at":"Wed 15 Apr, 09:30","body":["Saw Sarah's email. My numbers are right, aren't they? Sales has always reported it this way. Please don't let Finance change our dashboard without talking to me."]}],"evidence":[{"id":"gl","kind":"file","title":"finance_gl_q1_2026.csv (from Nina)","file":"data/experience/s02/finance_gl_q1_2026.csv","desc":"General ledger revenue accounts by posting period."},{"id":"dash","kind":"file","title":"dashboard_q1_2026.csv","file":"data/experience/s02/dashboard_q1_2026.csv","desc":"Net Sales by month as shown on the dashboard (use your own model from Sprint 01 if you built one)."},{"id":"orders","kind":"file","title":"orders.csv","file":"data/experience/company/orders.csv"},{"id":"lines","kind":"file","title":"order_lines.csv","file":"data/experience/company/order_lines.csv"},{"id":"returns","kind":"file","title":"returns.csv","file":"data/experience/company/returns.csv"},{"id":"fx","kind":"file","title":"fx_rates.csv","file":"data/experience/company/fx_rates.csv"},{"id":"policy","kind":"doc","title":"Finance policy manual, chapter 4: Revenue (extract)","body":["**4.1** Revenue from the sale of goods is recognised in the period in which the sale is posted to the ledger.","**4.2** Purchases by employees under the staff discount scheme are recorded against account 6950 (staff benefit cost recovery) and are not revenue.","**4.3** Customer returns are recorded in account 4900 in the period in which the returned goods are received, regardless of when the original sale was made.","**4.4** Postage refunded to customers on returns is recorded in account 4910 and reduces net revenue.","**4.5** Gift cards are recognised when redeemed, not when sold.","**4.6** Intercompany sales between Northwind Outdoors Inc. and Northwind Outdoors GmbH are eliminated on consolidation.","**4.7** Foreign-currency revenue is translated at the average rate of the month in which it is recognised."]},{"id":"kpi","kind":"table","title":"The Net Sales definition you agreed with Jordan in Sprint 01","cols":["Element","Dashboard"],"rows":[["Sales","Completed orders, by order date, after discount"],["Returns","Refunds deducted from the original order's period"],["Currency","EUR at the order month's average rate"],["Channels","All"]]}],"tasks":["Build a monthly reconciliation between the dashboard and the ledger.","Find every reason the numbers differ and quantify each one, so that they add up exactly to the gap.","Decide what the dashboard should do: match Finance, keep the Sales view, or show both, clearly labelled. Justify it.","Implement the corrected measure(s) and prove nothing else broke (regression check).","Write the reply to Sarah (and copy Jordan): short, factual, no blame."],"deliverables":[{"id":"rec","t":"Reconciliation table: dashboard → ledger, one line per cause, summing exactly to the gap","artifact":"validation-plan"},{"id":"rca","t":"Root cause note: which definitions each team uses, and why both are internally consistent","artifact":"incident-report"},{"id":"kpi","t":"Updated KPI dictionary with both definitions, named so nobody confuses them","artifact":"kpi-dictionary"},{"id":"dax","t":"Corrected measures in the model, with a regression check on the Sprint 01 numbers"},{"id":"mail","t":"Reply to the CFO, copying the VP Sales"}],"hints":["Nina says every month is off by a different amount, so it's several causes, not one. Read the policy extract line by line and ask of each one: does our dashboard do the same thing?","Compare which date each side uses for sales and for returns. Look closely at orders placed on the last evening of a month and at returns received in Q1 for orders placed in Q4.","Make a bridge: start from the dashboard number, change one rule at a time (channel, sales date, returns date, shipping refunds), and record the effect of each. The steps must sum to the gap to the cent."],"rubric":[{"id":"correct","n":"Technical correctness","w":30,"good":"Every cause found and quantified; the bridge sums exactly to the gap; the corrected measure equals the ledger to the dollar."},{"id":"invest","n":"Investigation quality","w":20,"good":"Changed one rule at a time, by month, and used the policy as the specification rather than guessing."},{"id":"testing","n":"Testing","w":15,"good":"A regression check shows the Sprint 01 measures and other pages still return the agreed values."},{"id":"maint","n":"Maintainability","w":10,"good":"Two clearly named measures (e.g. Net Sales (Sales view) and Net Revenue (Ledger)) instead of one ambiguous one; definitions documented."},{"id":"comm","n":"Communication","w":25,"good":"The CFO gets the answer, the size of each cause and the fix in under 150 words, and Jordan is not made wrong: both definitions are valid for their purpose."}],"retro":["Which of the causes would you have found without the policy document?","Should a sales dashboard ever show a different \"revenue\" from the ledger? When is that legitimate?","How would you stop the next analyst from creating a third definition?","What did you say to Jordan, and was it the same message you sent Sarah?"],"refs":[{"title":"Use DAX variables to make measures easier to debug","url":"https://learn.microsoft.com/en-us/dax/best-practices/dax-variables"},{"title":"USERELATIONSHIP (role-playing dates)","url":"https://learn.microsoft.com/en-us/dax/userelationship-function-dax"}]},
"d01":{"$schema":"../../schema/scenario.schema.json","id":"d01","slug":"d01-requirements-interview","type":"drill","stage":"analyst","order":3,"title":"Four requests, zero requirements","seo":"BI requirements gathering drill: practise the questions to ask stakeholders before building a Power BI report (definitions, grain, latency, security, reconciliation).","summary":"Four stakeholders send one-line requests. Pick the questions you'd ask before building anything, then check them against an experienced BI developer's.","minutes":30,"skills":["communication","modeling","governance"],"ticket":{"id":"REQ-301","kind":"ticket","priority":"Normal","reporter":"elena","opened":"Thu 23 Apr 2026, 10:00","labels":["requirements"]},"impact":"Most BI rework comes from building the right thing to the wrong definition. Ten minutes of questions saves a week of rebuilding, and a dashboard nobody trusts.","messages":[{"from":"elena","to":"you","via":"chat","at":"Thu 23 Apr, 10:00","body":["Four new requests came in this morning. Before anyone builds anything, I'd like to see the questions you'd ask each requester. Don't ask everything: ask what changes the design."]}],"evidence":[],"interactive":{"type":"questions","intro":"Tick the questions you would ask, then press Check. Good questions change the design or the numbers; weak ones are answerable by you, too vague, or not the requester's to answer.","prompts":[{"from":"sarah","request":"We need profitability by customer.","options":[{"q":"Which costs should profitability include: product cost only, or also shipping, returns, discounts and service costs?","good":true,"why":"\"Profit\" means four different numbers depending on which costs are in. This decides the model."},{"q":"At what level: individual customer, customer segment, or account group (for wholesale chains)?","good":true,"why":"The grain decides whether cost allocation is even possible."},{"q":"Do you want a bar chart or a table?","good":false,"why":"A design detail you can propose later; it doesn't change what data you need."},{"q":"Which source should the numbers reconcile to: the ledger or the sales system?","good":true,"why":"If it must tie to the ledger, posting dates and Finance's definitions apply (see Sprint 02)."},{"q":"How often do you need it refreshed?","good":true,"why":"Monthly after close and daily lead to different designs and sources."},{"q":"Should I use Power BI?","good":false,"why":"That's your decision, not the CFO's."}]},{"from":"jordan","request":"Can you just add margin to the existing dashboard?","options":[{"q":"Margin before or after returns and discounts, and should it match what Finance reports?","good":true,"why":"\"Just add margin\" hides a definition decision, and margin is sensitive."},{"q":"Who should be able to see margin? Everyone who sees the dashboard today, including sales reps?","good":true,"why":"Cost and margin are often restricted; adding them to a widely shared report can be a leak."},{"q":"Which colour should margin be?","good":false,"why":"Not a requirement."},{"q":"What decision will you make with it?","good":true,"why":"The answer tells you whether you need margin % per product, per customer, or a trend."},{"q":"Is product cost available and trusted for all products, including discontinued ones?","good":false,"why":"Important, but that's a question for the data owner (Kenji or Finance), not for Jordan."}]},{"from":"jordan","request":"Marketing wants near-real-time reporting.","options":[{"q":"What decision will someone take within minutes of seeing the data, and who?","good":true,"why":"If nobody acts within minutes, \"real time\" is a wish, and an expensive one."},{"q":"What latency is actually acceptable: 1 minute, 15 minutes, 1 hour?","good":true,"why":"Each answer leads to a different architecture (DirectQuery, frequent refresh, streaming, Direct Lake)."},{"q":"Which metrics need to be fresh, and which can be daily?","good":true,"why":"Usually only one or two numbers need freshness; the rest can stay cheap and fast."},{"q":"Can the source system handle frequent queries?","good":false,"why":"Vital, but ask the data engineer, not Marketing."},{"q":"Do you want it in Power BI or Excel?","good":false,"why":"Doesn't change the latency question."}]},{"from":"sarah","request":"Finance needs the numbers to match the board pack.","options":[{"q":"Which numbers exactly, and match to what tolerance (to the dollar, to the thousand)?","good":true,"why":"\"The numbers\" is too vague to test. You need a list and a tolerance."},{"q":"Which version of the board pack is authoritative, and when is it locked each month?","good":true,"why":"Matching a moving target is impossible; you need the close calendar."},{"q":"Who signs off that the dashboard matches?","good":true,"why":"Acceptance needs an owner, otherwise it never ends."},{"q":"Can we change the board pack to match the dashboard instead?","good":false,"why":"The board pack is the controlled document; the dashboard follows it."}]}]},"tasks":["For each request, choose the questions you'd ask first, then press Check.","Write the three questions you think matter most across all four requests in your notes."],"deliverables":[{"id":"q","t":"A short requirements question list per request","artifact":"requirements"}],"hints":["A good requirements question changes the model, the number or who may see it. If the answer wouldn't change what you build, don't ask it yet."],"rubric":[{"id":"def","n":"Definitions","w":35,"good":"Asked what each key word (profit, margin, real time, match) means in numbers."},{"id":"use","n":"Purpose and decisions","w":25,"good":"Asked what decision each output supports, which drives grain and latency."},{"id":"sec","n":"Security and audience","w":20,"good":"Noticed when a request widens who sees sensitive data."},{"id":"focus","n":"Focus","w":20,"good":"Didn't ask cosmetic or self-answerable questions; directed technical questions to the right person."}],"retro":["Which request would you have built wrong without asking?","Which question will you now ask on every request?"],"refs":[{"title":"Power BI implementation planning: requirements and BI strategy","url":"https://learn.microsoft.com/en-us/power-bi/guidance/powerbi-implementation-planning-bi-strategy-overview"}]},
"d02":{"$schema":"../../schema/scenario.schema.json","id":"d02","slug":"d02-uat-region-total","type":"drill","stage":"analyst","order":4,"title":"\"The Region total doesn't match Excel\"","seo":"Power BI user acceptance testing drill: a tester reports that region totals don't match Excel. Reproduce, compare definitions and decide whether it's a defect or a requirement mismatch.","summary":"Nina's UAT finding says the report's region totals don't match her Excel. Reproduce it, explain it and decide: defect or requirement mismatch?","minutes":60,"skills":["testing","modeling","communication"],"prereq":["s01"],"ticket":{"id":"UAT-017","kind":"uat","priority":"Normal","reporter":"nina","opened":"Tue 21 Apr 2026, 15:40","labels":["uat","regions"]},"impact":"UAT is where the business decides whether to trust a report. Calling a definition difference a \"bug\" (or a real bug \"by design\") loses that trust for months.","messages":[{"from":"nina","to":"you","via":"email","at":"Tue 21 Apr, 15:40","subject":"UAT-017: Region totals wrong","body":["Hi, testing the Q1 dashboard: West shows $60,740 but my Excel says $64,461. Central is the other way round. Europe matches. Total matches. Logged as a defect, severity high. Screenshot and my Excel attached."]}],"evidence":[{"id":"xl","kind":"file","title":"nina_excel_region_totals.csv","file":"data/experience/d02/nina_excel_region_totals.csv"},{"id":"rep","kind":"file","title":"report_region_totals.csv","file":"data/experience/d02/report_region_totals.csv"},{"id":"wiki","kind":"doc","title":"Sales terminology (team wiki)","body":["**Regions**: Sales are credited to the region of the store or rep that made the sale."]},{"id":"orders","kind":"file","title":"orders.csv","file":"data/experience/company/orders.csv"},{"id":"customers","kind":"file","title":"customers.csv","file":"data/experience/company/customers.csv"}],"tasks":["Reproduce both numbers from the data.","Explain the difference in one sentence.","Decide: defect, requirement mismatch, or test error, and record the UAT outcome.","Propose what the report should do so testers don't trip over it again."],"deliverables":[{"id":"uat","t":"UAT log entry: test case, expected, actual, evidence, status, owner, notes","artifact":"uat-plan"},{"id":"reply","t":"Reply to Nina"}],"hints":["Totals match and Europe matches; only US regions move between each other. Which two region columns exist, and which one did each side use?","Count orders where the sales region differs from the customer's home region."],"rubric":[{"id":"repro","n":"Reproduction","w":30,"good":"Both sets of numbers rebuilt from the data, to the dollar."},{"id":"class","n":"Classification","w":30,"good":"Correctly classified as a requirement mismatch (two valid definitions), with the wiki as evidence."},{"id":"doc","n":"UAT documentation","w":20,"good":"Log entry complete: expected, actual, evidence, status, owner."},{"id":"comm","n":"Communication","w":20,"good":"Nina's work is respected; the report gets a clearer label or a second view."}],"retro":["How would the report's design have prevented this finding?"],"refs":[{"title":"Active vs inactive relationship guidance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/relationships-active-inactive"}]},
"s03":{"$schema":"../../schema/scenario.schema.json","id":"s03","slug":"s03-payroll-security-incident","type":"sprint","stage":"developer","order":1,"title":"A regional manager can see other regions' payroll","seo":"Power BI row-level security incident: a West regional manager can see East payroll. Reproduce, find the RLS weakness, fix it and build an RLS test matrix.","summary":"The West regional manager opened the Sales & Payroll model in Excel and saw salaries for every region. Contain it, find out why, fix it and prove it's fixed.","minutes":240,"skills":["security","modeling","testing","governance","communication"],"prereq":["s01"],"next":"s04","verified":{"date":"2026-10-01","context":"RLS and OLS behaviour per Microsoft Learn (Row-level security, Object-level security), Sept 2026","review_after_days":180},"ticket":{"id":"INC-2031","kind":"incident","severity":"SEV2","priority":"High","status":"Open","reporter":"dana","opened":"Tue 14 Apr 2026, 08:31","due":"Containment within 4 hours","labels":["security","rls","payroll","privacy"]},"story":"Sam built the Sales & Payroll model last quarter so regional managers could see sales and their own team's pay in one place. It was published as an app with an audience per region.","impact":"Salary data is personal data. A manager seeing other teams' pay is a privacy breach that Compliance may have to log, and it damages trust between managers and HR. Until it is contained, every day adds people who might have seen something they shouldn't.","messages":[{"from":"dana","to":"elena","via":"email","at":"Tue 14 Apr, 08:31","subject":"Payroll numbers?","body":["Hi Elena, quick one. I opened the Sales & Payroll model in Excel this morning (Analyze in Excel) to build my own team summary and the pivot shows payroll for East and Central as well as West, names and all. I don't think I'm supposed to see that? In the app I only see West.","I haven't shared the file with anyone. Dana"]},{"from":"elena","to":"you","via":"chat","at":"Tue 14 Apr, 08:40","body":["Treat this as SEV2 until we know more. Contain first, investigate second. Sam is on leave today, so it's yours. I've told Ava (Compliance); she will want a written timeline.","Don't delete anything: logs and the current model definition are evidence."]},{"from":"ava","to":"you","via":"email","at":"Tue 14 Apr, 09:15","subject":"INC-2031: what I need","body":["Hello. For my records I need: when the exposure started, who could have seen what, what was done to stop it and when, and how we know it is fixed. Please keep a timeline as you go.","Ava Martin, Compliance"]}],"evidence":[{"id":"roles","kind":"file","title":"roles.tmdl (from the published model)","file":"data/experience/s03/roles.tmdl","desc":"The model's security roles as currently deployed."},{"id":"rels","kind":"file","title":"relationships.csv","file":"data/experience/s03/relationships.csv","desc":"All relationships in the model, including cross-filter direction and whether they are active."},{"id":"bridge","kind":"file","title":"security_user_region.csv","file":"data/experience/s03/security_user_region.csv","desc":"SecurityUserRegion table: which user may see which region."},{"id":"emp","kind":"file","title":"employees.csv","file":"data/experience/s03/employees.csv"},{"id":"pay","kind":"file","title":"payroll_q1_2026.csv","file":"data/experience/s03/payroll_q1_2026.csv","desc":"FactPayroll: monthly gross pay and bonus per employee."},{"id":"filters","kind":"file","title":"report_page_filters.csv","file":"data/experience/s03/report_page_filters.csv","desc":"Filters configured in the report (exported from the PBIR files)."},{"id":"log","kind":"file","title":"activity_log.csv","file":"data/experience/s03/activity_log.csv","desc":"Activity events for the model and app since Monday."},{"id":"app","kind":"doc","title":"App configuration","body":["- App: Sales & Payroll. Audiences: West, South, East, Central, Europe managers; Sales reps; Finance.\n- Each manager audience sees the Payroll by region page; reps don't see that page.\n- Groups SG-Sales-Managers and SG-Sales-Reps have Build permission on the model so people can use Analyze in Excel."]}],"tasks":["Contain the exposure within the first hour, without breaking the app for everyone else. Record what you did and when.","Reproduce the problem with View as role (or by querying as the user) and capture the evidence.","Find every reason the security didn't hold. There may be more than one.","Fix the model so security is enforced by the engine, not by the report.","Build an RLS/OLS test matrix covering each role and a representative user, and run it.","Classify the severity, write the incident notes Ava asked for, and list preventive actions."],"deliverables":[{"id":"contain","t":"Containment action and timeline (what, who, when)","artifact":"incident-report"},{"id":"rca","t":"Root cause analysis: each weakness, with evidence","artifact":"postmortem"},{"id":"fix","t":"The corrected roles (TMDL or screenshots of Manage roles)"},{"id":"matrix","t":"RLS/OLS test matrix: user, role, expected regions, forbidden regions, payroll visible?, expected total, actual, pass/fail","artifact":"rls-test-matrix"},{"id":"comms","t":"Notes for Compliance: exposure window, who could see what, how we know it's fixed"}],"hints":["The app showed Dana only West, but Excel showed everything. Which of those two is enforced by the engine and which by the report? Look at report_page_filters.csv.","RLS filters flow along active relationships only. Which table holds the RLS filter, and is there an active path from that table to FactPayroll? relationships.csv has the answer.","There is a second problem that Dana didn't report. Read roles.tmdl again and ask what a Sales Rep can see of FactPayroll, then check who used Explore data."],"rubric":[{"id":"contain","n":"Containment","w":15,"good":"Exposure stopped within the hour (e.g. remove Build permission or the payroll table from the app audience) without taking sales reporting down for everyone; timeline recorded."},{"id":"correct","n":"Technical correctness","w":25,"good":"Both weaknesses found and fixed in the model: payroll filtered by the user's regions through an active path, and reps blocked from payroll by object-level security."},{"id":"testing","n":"Testing","w":25,"good":"A test matrix with every role and at least one user per role, expected vs actual payroll totals, run after the fix, all passing, kept for future releases."},{"id":"invest","n":"Investigation quality","w":15,"good":"Evidence-based: activity log, relationships and roles cited; distinguishes report filters from security."},{"id":"comm","n":"Communication","w":20,"good":"Ava gets a factual timeline and exposure statement; Dana is thanked for reporting; no blame on Sam in writing."}],"retro":["Why did the app look secure to everyone who tested it?","What would have caught this before release? Write it as a test that runs on every deployment.","Should payroll be in the same model as sales at all? Argue both sides.","Who else might have seen data they shouldn't, and how would you find out?"],"refs":[{"title":"Row-level security (RLS) with Power BI","url":"https://learn.microsoft.com/en-us/fabric/security/service-admin-row-level-security"},{"title":"Object-level security (OLS)","url":"https://learn.microsoft.com/en-us/fabric/security/service-admin-object-level-security"},{"title":"RLS guidance in Power BI Desktop","url":"https://learn.microsoft.com/en-us/power-bi/guidance/rls-guidance"}]},
"s05":{"$schema":"../../schema/scenario.schema.json","id":"s05","slug":"s05-one-revenue-semantic-model","type":"sprint","stage":"developer","order":2,"title":"Three models, three Revenues","seo":"Power BI shared semantic model exercise: Sales, Finance and Operations each have a Revenue measure with a different value. Inventory, standardise, certify and migrate thin reports.","summary":"Sales, Finance and Operations each have a model with a measure called Revenue, and all three disagree. The CEO wants one version of the truth.","minutes":360,"skills":["modeling","governance","dax","service","communication","architecture"],"prereq":["s02"],"next":"s06","ticket":{"id":"BI-1103","kind":"ticket","priority":"High","status":"Open","reporter":"grace","opened":"Mon 11 May 2026, 10:02","due":"Plan by Fri 22 May; migration by end of June","labels":["semantic-model","certification","governance"]},"story":"After the Finance dispute (Sprint 02) the sales dashboard shows both Net Sales and the ledger's Net Revenue. Then the leadership meeting got three different Q1 revenue figures from three different reports.","impact":"When three reports disagree, every meeting starts with an argument about numbers instead of decisions. Each copy of the model also costs refresh time, capacity and maintenance, and each one can drift further.","messages":[{"from":"grace","to":"elena","via":"email","at":"Mon 11 May, 10:02","subject":"One number","body":["Elena, this morning I saw three different Q1 revenue figures: Jordan's, Sarah's and one from Operations. All three were called \"Revenue\". I don't care which one is right; I care that we have one answer and that everyone uses it.","Please come back with a plan. Grace"]},{"from":"elena","to":"you","via":"chat","at":"Mon 11 May, 10:30","body":["This is yours. I want an inventory of what exists, a proposal for one certified model, a migration plan for the reports and a clear owner for each definition.","Careful: \"one number\" doesn't mean one measure. It means nobody can be confused about which measure they're looking at."]},{"from":"kenji","to":"you","via":"chat","at":"Mon 11 May, 11:12","body":["FYI the Ops model reads from the shipments table in the warehouse, not orders. Ops counts revenue when stuff leaves the building. Their dashboard drives the warehouse staffing plan, so don't break it."]}],"evidence":[{"id":"values","kind":"file","title":"revenue_by_model_q1_2026.csv","file":"data/experience/s05/revenue_by_model_q1_2026.csv","desc":"What each model's Revenue measure returns for Q1 2026."},{"id":"measures","kind":"file","title":"revenue_measures.tmdl","file":"data/experience/s05/revenue_measures.tmdl","desc":"The three Revenue measures, copied from each model's TMDL."},{"id":"reports","kind":"file","title":"report_inventory.csv","file":"data/experience/s05/report_inventory.csv","desc":"Reports built on the three models."},{"id":"s02","kind":"doc","title":"Outcome of BI-1057 (Sprint 02)","body":["Finance owns the ledger definition (Net Revenue). Sales keeps Net Sales by order date for pipeline and commission. Anything compared with the board pack uses the ledger measure."]}],"tasks":["Inventory the three models and their reports: what each Revenue measure means, who owns it, who depends on it.","Explain exactly why the three values differ (definitions, not bugs).","Design one shared, certified semantic model: its tables, its measures (with unambiguous names) and which one is the company's \"Revenue\".","Plan the migration of every report to thin reports on the shared model, in an order that never breaks a business process.","Define ownership: who owns each definition, who maintains the model, who can certify and who approves changes."],"deliverables":[{"id":"inv","t":"Inventory of models, measures, reports and owners"},{"id":"kpi","t":"KPI dictionary with each revenue definition, its owner and its use","artifact":"kpi-dictionary"},{"id":"design","t":"Shared model design: tables, grain, measures, security"},{"id":"plan","t":"Migration plan: report by report, with rollback","artifact":"release-notes"},{"id":"owner","t":"Ownership matrix (RACI) for definitions and the model","artifact":"ownership-matrix"},{"id":"adr","t":"Short decision record: one shared model vs departmental models","artifact":"adr"}],"hints":["Read the three measures' comments: each uses a different date (order, posting, ship) and a different base table. None is wrong.","One shared model can hold all three, but they can't all be called Revenue. Name each after what it measures, and decide which one gets to be the company's headline figure (and who decides).","Migrate in an order that protects processes: what happens to the Commission Calculator and the warehouse staffing plan on migration day? What does a report with no owner tell you?"],"rubric":[{"id":"frame","n":"Problem framing","w":15,"good":"States that the problem is ambiguous naming and ownership, not three wrong numbers."},{"id":"correct","n":"Technical correctness","w":20,"good":"The three values are explained by definition; the shared model reproduces each one exactly under a distinct name."},{"id":"design","n":"Design and maintainability","w":20,"good":"One model at order-line grain with shipments and the ledger bridge; measures named by meaning; display folders and descriptions; RLS kept."},{"id":"plan","n":"Migration and risk","w":20,"good":"Report-by-report plan with test, cut-over, rollback and deprecation dates; dependent processes (commissions, staffing) protected."},{"id":"own","n":"Ownership and governance","w":15,"good":"Business owner per definition, technical owner for the model, certification criteria, change approval."},{"id":"comm","n":"Communication","w":10,"good":"Grace gets a one-paragraph plan; each department hears what changes for them and when."}],"retro":["What would happen if you had simply deleted two of the three measures?","Who should be allowed to change the definition of the company's Revenue?","How will you stop a fourth model with a fourth Revenue appearing next year?"],"refs":[{"title":"Endorsement: promote and certify content","url":"https://learn.microsoft.com/en-us/fabric/governance/endorsement-overview"},{"title":"Connect to semantic models (thin reports)","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-datasets-discover-across-workspaces"},{"title":"Power BI implementation planning: content ownership","url":"https://learn.microsoft.com/en-us/power-bi/guidance/fabric-adoption-roadmap-content-ownership-and-management"}]},
"d05":{"$schema":"../../schema/scenario.schema.json","id":"d05","slug":"d05-report-retirement","type":"drill","stage":"developer","order":3,"title":"Usage dropped 70%. Retire it?","seo":"Power BI governance drill: a report's usage dropped 70%. Check lineage, subscriptions and dependencies before retiring anything.","summary":"Regional Sales Weekly lost most of its viewers after the certified Sales Overview launched. Elena asks whether it can be deleted to tidy up.","minutes":30,"skills":["governance","service","communication"],"prereq":["s05"],"ticket":{"id":"GOV-044","kind":"ticket","priority":"Low","reporter":"elena","opened":"Mon 25 May 2026, 14:00","labels":["governance","retirement","lineage"]},"impact":"Unused content costs refresh, capacity and confusion. Deleting content that something still depends on breaks payroll, a dashboard or a finance spreadsheet, usually on the day it's needed.","messages":[{"from":"elena","to":"you","via":"chat","at":"Mon 25 May, 14:00","body":["Regional Sales Weekly is down about 70% since Sales Overview launched. Can we delete it and its model to tidy up? Check first, please."]}],"evidence":[{"id":"usage","kind":"file","title":"usage_weekly.csv","file":"data/experience/d05/usage_weekly.csv"},{"id":"lineage","kind":"file","title":"lineage.csv","file":"data/experience/d05/lineage.csv"},{"id":"subs","kind":"file","title":"subscriptions.csv","file":"data/experience/d05/subscriptions.csv"}],"tasks":["Confirm the usage drop and who still uses the report.","List every dependency on the report and on its model.","Recommend: retire, keep, or retire in steps, with a timeline and who to notify."],"deliverables":[{"id":"plan","t":"Retirement plan with dependencies, notifications and dates","artifact":"release-notes"}],"hints":["The report and its model are two different questions. What depends on the model, not just on the report?","Usage metrics don't show subscriptions, paginated reports or Excel files. lineage.csv and subscriptions.csv do."],"rubric":[{"id":"deps","n":"Dependency analysis","w":40,"good":"Finds the Commission Statement (payroll), the dashboard tile, the Finance Excel file and the subscription."},{"id":"plan","n":"Plan","w":35,"good":"Retire the report in steps (notify, banner, read-only, archive); keep the model until the paginated report and Excel are repointed."},{"id":"comm","n":"Communication","w":25,"good":"Owners and remaining viewers notified with dates and the replacement."}],"retro":["What would have broken if you had deleted the model today?"],"refs":[{"title":"Lineage view","url":"https://learn.microsoft.com/en-us/fabric/governance/lineage"},{"title":"Usage metrics for reports","url":"https://learn.microsoft.com/en-us/power-bi/collaborate-share/service-modern-usage-metrics"}]},
"d06":{"$schema":"../../schema/scenario.schema.json","id":"d06","slug":"d06-change-requests","type":"drill","stage":"developer","order":4,"title":"Four change requests to a working model","seo":"Power BI change management drill: refactor a working model for four change requests (returns by return date, shipping refunds, salary security, 4-4-5 fiscal calendar) and quantify the impact.","summary":"The dashboard from Sprints 01 and 02 works. Now four change requests arrive. Assess the impact of each, then refactor without breaking what people rely on.","minutes":180,"skills":["modeling","dax","security","testing","communication"],"prereq":["s02","s03"],"ticket":{"id":"CR-118","kind":"change","priority":"Normal","reporter":"elena","opened":"Mon 20 Apr 2026, 09:00","labels":["change-request","refactoring"]},"impact":"Most BI work is changing systems that are already in use. Every change moves numbers people have already seen; doing it without impact analysis is how trust is lost.","messages":[{"from":"elena","to":"you","via":"email","at":"Mon 20 Apr, 09:00","subject":"Four CRs for the sales model","body":["- **CR1** (Sarah): returns should reduce revenue in the month the return is received, not the month of the original order.\n- **CR2** (Sarah): shipping refunds should also reduce revenue.\n- **CR3** (Ava): contractors in Europe must not see employee salary data.\n- **CR4** (Sarah): from FY2026 Finance reports on a 4-4-5 calendar starting Sunday 28 Dec 2025.","For each one: what changes, by how much for Q1 2026, what could break, and how you'll test it. Then implement them."]}],"evidence":[{"id":"lines","kind":"file","title":"order_lines.csv","file":"data/experience/company/order_lines.csv"},{"id":"orders","kind":"file","title":"orders.csv","file":"data/experience/company/orders.csv"},{"id":"returns","kind":"file","title":"returns.csv","file":"data/experience/company/returns.csv"},{"id":"emp","kind":"file","title":"employees.csv","file":"data/experience/s03/employees.csv"},{"id":"now","kind":"table","title":"Current dashboard values, Q1 2026","cols":["Measure","Value"],"rows":[["Gross Sales","$254,751"],["Net Sales","$244,409"]]}],"tasks":["Write an impact assessment per CR: what changes, the Q1 2026 effect in dollars, what else could break, how you'll test it.","Implement the four CRs as separate, reviewable changes.","Run a regression check on everything the CRs should not affect."],"deliverables":[{"id":"ia","t":"Impact assessment per change request","artifact":"release-notes"},{"id":"impl","t":"Implemented changes (DAX, model, roles, calendar table)"},{"id":"reg","t":"Regression results","artifact":"validation-plan"}],"hints":["CR1 and CR2 change the definition of an existing measure that people have already seen; decide whether to change it or add a new one.","CR4 moves the quarter boundaries: Q1 FY2026 is 13 weeks from 28 Dec 2025 to 28 Mar 2026. Compare it with calendar Q1 and explain the difference to Finance before they see it."],"rubric":[{"id":"impact","n":"Impact analysis","w":35,"good":"Dollar effect per CR computed correctly; dependencies named (reports, commissions, YoY comparisons)."},{"id":"impl","n":"Implementation","w":30,"good":"Separate changes; date table with 4-4-5 periods; OLS or column security for salary; returns by return date via the right relationship."},{"id":"reg","n":"Regression testing","w":20,"good":"Unaffected measures proven unchanged; affected ones reconciled to the impact assessment."},{"id":"comm","n":"Communication","w":15,"good":"Stakeholders told before the numbers change, with old and new side by side."}],"retro":["Which CR changed the most numbers for the fewest lines of code?","Which CR should have been rejected or clarified first?"],"refs":[{"title":"Create date tables in Power BI Desktop","url":"https://learn.microsoft.com/en-us/power-bi/guidance/model-date-tables"},{"title":"Object-level security","url":"https://learn.microsoft.com/en-us/fabric/security/service-admin-object-level-security"}]},
"s04":{"$schema":"../../schema/scenario.schema.json","id":"s04","slug":"s04-monday-performance-incident","type":"sprint","stage":"senior","order":1,"title":"The executive dashboard takes 18 seconds","seo":"Power BI performance tuning scenario: an executive page takes 18 seconds. Use Performance Analyzer, Server Timings and VertiPaq metrics to find formula-engine and storage-engine bottlenecks, then prove the fix.","summary":"Leadership opens the executive page every Monday at 9:00 and waits 18 seconds. Find out why with evidence, fix it, and prove the improvement.","minutes":300,"skills":["performance","dax","modeling","testing","communication"],"prereq":["s02"],"next":"s05","verified":{"date":"2026-10-01","context":"Performance Analyzer, DAX query view and optimization guidance (Microsoft Learn, Sept 2026); DAX Studio 3.x Server Timings","review_after_days":180},"ticket":{"id":"INC-2044","kind":"incident","severity":"SEV3","priority":"Medium","status":"Open","reporter":"grace","opened":"Mon 4 May 2026, 09:12","due":"Before next Monday's leadership meeting","labels":["performance","executive","dax"]},"story":"Since Sprint 02 the company sales model carries both the Sales and the ledger definitions. It now has 31 million order lines from 2023 onwards, and the executive page has gained a few visuals.","impact":"Eight executives wait for the page at the start of every leadership meeting, and some have started asking for Excel exports instead. A slow report is an abandoned report, and the capacity is busiest exactly then.","messages":[{"from":"grace","to":"elena","via":"email","at":"Mon 4 May, 09:12","subject":"Dashboard","body":["Elena, the dashboard took most of a minute to load this morning, again. We ended up looking at last week's PDF. Please sort it out before next Monday. Grace"]},{"from":"elena","to":"you","via":"chat","at":"Mon 4 May, 09:20","body":["Grace's \"most of a minute\" is more like 18 seconds on my machine, but she's right that it's not acceptable. I captured Performance Analyzer and DAX Studio output this morning; it's all in the folder.","I want a before/after table with real measurements, not \"it feels faster\". And nothing on the page may change its numbers."]},{"from":"sam","to":"you","via":"chat","at":"Mon 4 May, 10:05","body":["I added Customers Above Average and Store Sales YTD in March, they were urgent requests. Last Refreshed was always there. Maybe we just need a bigger capacity? F128 would sort it."]}],"evidence":[{"id":"pa","kind":"file","title":"performance_analyzer.json","file":"data/experience/s04/performance_analyzer.json","desc":"Performance Analyzer export of the executive page, cold cache, Monday 08:55."},{"id":"st","kind":"file","title":"server_timings.csv","file":"data/experience/s04/server_timings.csv","desc":"DAX Studio Server Timings for the four slowest visuals' queries."},{"id":"vp","kind":"file","title":"vertipaq_columns.csv","file":"data/experience/s04/vertipaq_columns.csv","desc":"VertiPaq Analyzer: column sizes and cardinality."},{"id":"dax","kind":"file","title":"measures.dax","file":"data/experience/s04/measures.dax","desc":"The measures on the page, as they are today."},{"id":"notes","kind":"file","title":"model_notes.md","file":"data/experience/s04/model_notes.md"},{"id":"repro","kind":"doc","title":"Reproduce it on your machine (optional)","body":["Generate a big fact table with `node tools/generate-enterprise-data.js --rows 2000000` (see Resources → Enterprise scale pack) and load fact_sales.csv and dim_customer.csv into Power BI Desktop. The measures in measures.dax work against those columns, so you can measure your own before and after with Performance Analyzer and DAX Studio."]}],"tasks":["Establish a baseline: which visuals cost the most, and is each one formula-engine bound or storage-engine bound?","Find the root cause of each slow visual, with evidence from the files.","Rewrite or remodel so the page is fast without changing any number on it.","Measure again and produce a before/after table: Visual | Before | After | Improvement | Root cause.","Propose a performance budget for this page, and explain to Elena whether a bigger capacity is the answer.","Write two versions of the result: one for Grace, one for the engineers."],"deliverables":[{"id":"base","t":"Baseline: per-visual timings and FE/SE split"},{"id":"rca","t":"Root cause per slow visual, with the evidence line that proves it","artifact":"postmortem"},{"id":"fix","t":"Optimised measures and model changes (DAX/TMDL)"},{"id":"ba","t":"Before/after table with improvement %","artifact":"performance-report"},{"id":"reg","t":"Regression check: every visual returns the same values as before"},{"id":"two","t":"Executive note and engineering note (same facts, two audiences)"}],"hints":["Sort the Performance Analyzer events by DAX query time. Three visuals account for most of the page. For each, look up its row in server_timings.csv: is the time in the formula engine (FE) or the storage engine (SE)?","Thousands of small SE queries plus a CallbackDataID means something is evaluated row by row. Look at what Customers Above Average recalculates for every customer. A FILTER over ALL(FactSales) materialises the whole table. A MAX over a 31-million-value datetime column is a full column scan.","Check vertipaq_columns.csv against what the page actually uses. Then check the relationship the model notes describe as \"Both\"."],"rubric":[{"id":"invest","n":"Investigation quality","w":25,"good":"Every claimed cause is backed by a specific line of evidence (FE/SE split, SE query count, column size), not by intuition."},{"id":"correct","n":"Technical correctness","w":25,"good":"Each rewrite returns identical results; the fixes address the cause (variable outside the iterator, column filter instead of table filter, removed high-cardinality column, single-direction relationship)."},{"id":"perf","n":"Performance","w":20,"good":"Page meets a stated budget (e.g. under 3 seconds cold) with measured before/after numbers."},{"id":"testing","n":"Testing","w":10,"good":"Regression check proves no visual changed its values; the measurement method is repeatable (cold cache, same machine)."},{"id":"comm","n":"Communication","w":20,"good":"Grace's version has no jargon and states the result and the cost; the engineering version has the numbers. The capacity question is answered with evidence."}],"retro":["Which fix gave the biggest improvement for the least risk?","Would F128 have fixed it? What would it have cost and what would it have hidden?","What check would stop a slow measure reaching production next time?","Why did the page get slower over two months when \"nobody changed the measures\"?"],"refs":[{"title":"Optimization guide for Power BI","url":"https://learn.microsoft.com/en-us/power-bi/guidance/power-bi-optimization"},{"title":"Use Performance Analyzer","url":"https://learn.microsoft.com/en-us/power-bi/create-reports/performance-analyzer"},{"title":"Avoid using FILTER as a filter argument","url":"https://learn.microsoft.com/en-us/dax/best-practices/dax-avoid-avoid-filter-as-filter-argument"},{"title":"Bi-directional relationship guidance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/relationships-bidirectional-filtering"}]},
"s08":{"$schema":"../../schema/scenario.schema.json","id":"s08","slug":"s08-cfo-refresh-outage","type":"sprint","stage":"senior","order":2,"title":"The board pack refresh failed at 06:17","seo":"Power BI incident response scenario: the production semantic model refresh failed before the CFO's board meeting. Triage, mitigate, find the root causes, communicate and write the postmortem.","summary":"The Finance Board Pack model failed to refresh at 06:17. The CFO presents from it at 08:30. Decide what to do in the next hour, then fix it properly.","minutes":240,"skills":["service","power-query","communication","governance","testing"],"prereq":["s07"],"next":"s09","verified":{"date":"2026-10-01","context":"Refresh troubleshooting and gateway data source docs (Microsoft Learn, Sept 2026)","review_after_days":180},"ticket":{"id":"INC-2071","kind":"incident","severity":"SEV1","priority":"Critical","status":"Open","reporter":"nina","opened":"Mon 8 Jun 2026, 07:02","due":"CFO presents at 08:30","labels":["refresh","gateway","schema-change","board"]},"story":"Finance closed May on Friday 5 June at 18:00. The Finance Board Pack model refreshes every day at 05:30 and normally finishes by 06:10. Sam, the model's listed owner, is on holiday this week.","impact":"The CFO presents May results to the board at 08:30. If she presents wrong numbers, or cancels because she can't trust them, that's a board-level incident. The clock matters as much as the cause.","messages":[{"from":"service","to":"sam","via":"alert","at":"Mon 8 Jun, 06:17","subject":"Refresh failed: Finance Board Pack","body":["Your semantic model Finance Board Pack in workspace Finance Board Pack couldn't be refreshed. DM_GWPipeline_Gateway_MashupDataAccessError. (Delivered to sam.patel@northwind.example; out-of-office reply sent.)"]},{"from":"nina","to":"you","via":"chat","at":"Mon 8 Jun, 07:02","body":["Morning! The board pack dashboard says \"Data refreshed: Sun 7 Jun 06:05\". Sarah presents at 08:30 from it. Is that OK? Should it say today? I'm panicking a bit."]},{"from":"sarah","to":"you","via":"email","at":"Mon 8 Jun, 07:20","subject":"Board pack","body":["I'm told there's a problem with the board pack data. I need to know by 07:45 whether I can present from it, and if not, what I should use instead. Sarah"]},{"from":"kenji","to":"you","via":"chat","at":"Mon 8 Jun, 07:24","body":["Heard there's a refresh issue. Nothing failed on our side overnight; the DW loads were all green. Shout if you need anything."]}],"evidence":[{"id":"err","kind":"file","title":"refresh_error.json","file":"data/experience/s08/refresh_error.json","desc":"Error details from the refresh history in the Service."},{"id":"hist","kind":"file","title":"refresh_history.csv","file":"data/experience/s08/refresh_history.csv"},{"id":"gw","kind":"file","title":"gateway_status.csv","file":"data/experience/s08/gateway_status.csv"},{"id":"cols","kind":"file","title":"vw_customer_columns.csv","file":"data/experience/s08/vw_customer_columns.csv","desc":"Columns of dbo.vw_Customer yesterday and today (from the DW's schema history)."},{"id":"cal","kind":"file","title":"change_calendar.csv","file":"data/experience/s08/change_calendar.csv","desc":"IT change calendar for the weekend."},{"id":"cred","kind":"file","title":"datasource_credentials.csv","file":"data/experience/s08/datasource_credentials.csv"},{"id":"close","kind":"doc","title":"Finance close calendar (May 2026)","body":["- Last postings for May: Fri 5 Jun, 18:00. Ledger locked for May after that.\n- Board pack figures = May closed ledger. June postings are not shown in the pack."]}],"tasks":["By 07:45: decide whether Sarah can present from the dashboard as it is, and tell her. Base it on evidence, not hope.","Restore a successful refresh as soon as it is safe, without making an emergency change that could make things worse.","Find every root cause (there may be more than one) and fix them permanently.","Keep stakeholders updated on a schedule, even when there's no news.","Write the incident report and the postmortem with preventive actions and owners."],"deliverables":[{"id":"decision","t":"The 07:45 answer to the CFO, with the evidence behind it"},{"id":"updates","t":"Stakeholder updates (time-stamped)"},{"id":"ir","t":"Incident report: summary, impact, detection, timeline, root cause, mitigation, permanent fix","artifact":"incident-report"},{"id":"pm","t":"Blameless postmortem with preventive actions, owners and dates","artifact":"postmortem"},{"id":"rb","t":"Runbook update for refresh failures","artifact":"runbook"}],"hints":["Before fixing anything, answer the CFO's real question: does Sunday 06:05's data contain everything the board pack shows? Compare the refresh history with the close calendar.","refresh_error.json lists two separate errors on two separate sources. Find a weekend change in change_calendar.csv that explains each one.","One fix belongs in the model (or the view), the other in the gateway connection. A full refresh takes ~35 minutes: work out the latest time you can start one and still be safe, and whether you need it at all before 08:30."],"rubric":[{"id":"triage","n":"Triage and impact analysis","w":25,"good":"Establishes by 07:45 that Sunday's data already contains the closed May ledger, so the CFO can present; says so clearly with the data timestamp."},{"id":"rca","n":"Root cause","w":20,"good":"Both causes identified with evidence: CHG-4471 renamed CustomerSegment, CHG-4472 rotated the treasury service account password."},{"id":"fix","n":"Mitigation and permanent fix","w":20,"good":"Safe mitigation (credential update, Power Query or view alias), a verified refresh, and permanent changes: contract for the view, credential managed by owner, alerts to a team."},{"id":"comm","n":"Communication","w":20,"good":"Scheduled updates; the CFO gets a yes/no with reasons; the postmortem is blameless and readable by non-engineers."},{"id":"prevent","n":"Prevention","w":15,"good":"Actions with owners and dates: alert routing, schema change notification/contract, credential rotation process, failure-tolerant design."}],"retro":["What would you have done at 07:05 if the close had been on Sunday night instead of Friday?","Which of the two causes was a process failure and which was a technical one?","The failure email went to someone on holiday. What should alerting look like for a SEV1 model?","How would you know about the next upstream schema change before it breaks you?"],"refs":[{"title":"Troubleshoot refresh scenarios","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-troubleshooting-refresh-scenarios"},{"title":"Manage data sources for a gateway","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-data-sources"},{"title":"Configure scheduled refresh (failure notifications)","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/refresh-scheduled-refresh"}]},
"d04":{"$schema":"../../schema/scenario.schema.json","id":"d04","slug":"d04-hotfix-or-rollback","type":"drill","stage":"senior","order":3,"title":"Hotfix, rollback or wait?","seo":"BI release management drill: a production KPI is wrong after a release. Choose between a normal release, a hotfix and a rollback, and justify it.","summary":"Release 2.3 went live last night. This morning one KPI on the sales app is wrong. The board pack is tomorrow. Choose: normal release, hotfix or rollback.","minutes":30,"skills":["deployment","testing","communication","architecture"],"prereq":["s07"],"ticket":{"id":"INC-2079","kind":"decision","severity":"SEV2","priority":"High","reporter":"jordan","opened":"Wed 10 Jun 2026, 08:15","labels":["release","hotfix","rollback"]},"impact":"Every option has a cost. Rolling back also undoes fixes people are waiting for; a rushed hotfix can break something else the day before the board pack; waiting leaves a wrong number in front of managers.","messages":[{"from":"jordan","to":"elena","via":"email","at":"Wed 10 Jun, 08:15","subject":"Avg order value is off","body":["Avg Order Value on the sales app jumped from about $210 to $340 overnight. Nothing like that happened in the business. Managers are asking."]},{"from":"elena","to":"you","via":"chat","at":"Wed 10 Jun, 08:30","body":["Your call; tell me by 10:00 and why. Release notes attached. Next normal release train is Thursday 15:00, after the board pack goes out."]}],"evidence":[{"id":"notes","kind":"doc","title":"Release 2.3 notes (deployed Tue 9 Jun, 18:00)","body":["- 14 changes. Includes: Staff exclusion fix for Finance (requested for the board pack), schema migration of FactReturns (new column ReturnChannel; the previous release can't read the new table), two new pages for Ops, and AOV now uses [Orders (completed)].\n- All tests passed in Test. Rollback: redeploy release 2.2 from Git (requires reverting the FactReturns schema migration in the warehouse first)."]},{"id":"diff","kind":"code","lang":"DAX","title":"The AOV change in release 2.3","body":"-- 2.2\nAvg Order Value = DIVIDE ( [Net Sales (orders)], [Orders] )\n\n-- 2.3\nAvg Order Value = DIVIDE ( [Net Sales (orders)], [Orders (completed)] )\n-- [Orders (completed)] = CALCULATE ( DISTINCTCOUNT ( FactSales[OrderID] ), FactSales[Status] = \"Completed\", FactSales[Channel] = \"Online\" )"}],"decision":{"adr":"CHG-2079","title":"How to correct Avg Order Value in production","question":"What do you do?","options":[{"id":"wait","t":"Wait for Thursday's normal release train","d":"No risk of a rushed change; the wrong KPI stays live until Thursday afternoon."},{"id":"hotfix","t":"Hotfix: a one-line change to [Orders (completed)], tested and deployed today through the pipeline","d":"Fast and small; needs a test and a deployment outside the train."},{"id":"rollback","t":"Roll back to release 2.2","d":"Restores the old AOV and everything else from before last night."}]},"tasks":["Find what's actually wrong in the AOV change.","Weigh the three options against the facts in the release notes.","Record your decision with its justification and the safeguards you'd require."],"deliverables":[{"id":"dec","t":"Decision with justification and safeguards"},{"id":"rn","t":"Hotfix release note (if you chose it)","artifact":"release-notes"}],"hints":["Read [Orders (completed)] carefully: it filters more than its name says.","What else would a rollback take away, and what has to happen in the warehouse before 2.2 can even run?"],"rubric":[{"id":"diag","n":"Diagnosis","w":30,"good":"Finds the extra Channel = \"Online\" filter that shrinks the denominator."},{"id":"dec","n":"Decision quality","w":35,"good":"Chooses a tested hotfix; rejects rollback because it removes the Finance fix needed for the board pack and requires reverting a schema migration; rejects waiting because managers act on the KPI today."},{"id":"safe","n":"Safeguards","w":20,"good":"Hotfix through the pipeline with a regression check of AOV and other KPIs, and a follow-up test so it can't recur."},{"id":"comm","n":"Communication","w":15,"good":"Jordan and the managers told what was wrong and when it's fixed."}],"retro":["Which test in Test would have caught this?","When is a rollback the right answer?"],"refs":[{"title":"Deployment pipelines: deploy content","url":"https://learn.microsoft.com/en-us/fabric/cicd/deployment-pipelines/deploy-content"}]},
"d08":{"$schema":"../../schema/scenario.schema.json","id":"d08","slug":"d08-explain-it-twice","type":"drill","stage":"senior","order":4,"title":"Explain it twice","seo":"Communication drill for BI developers: explain the same technical finding to an executive and to an engineer, using Problem, Impact, Evidence, Options, Recommendation, Risk, Ask.","summary":"Same finding, two audiences. Write the executive version and the engineering version, using the senior conversation structure.","minutes":30,"skills":["communication","performance"],"prereq":["s04"],"ticket":{"id":"COMM-12","kind":"ticket","priority":"Normal","reporter":"elena","opened":"Tue 12 May 2026, 16:00","labels":["communication"]},"impact":"Senior developers are trusted because they can be understood. The same facts, told the wrong way, get either ignored by executives or dismissed by engineers.","messages":[{"from":"elena","to":"you","via":"chat","at":"Tue 12 May, 16:00","body":["Grace asked me why the capacity is near its limit every morning, and Kenji asked the same thing in the platform channel. Same facts below. Write both replies. Max 120 words each."]}],"evidence":[{"id":"facts","kind":"doc","title":"The facts","body":["- Capacity F64. Weekday 08:30–09:30 interactive load peaks at 96% of CU; throttling (delays) seen on 3 mornings last week.\n- Two causes: the Sales model refresh was moved to 08:00 by mistake (it used to run at 05:30), and a new Marketing report runs 40 visuals per page with no filters.\n- Options: move the refresh back (free, today); redesign the Marketing report (2 days); upgrade to F128 (doubles the cost).\n- Recommendation: first two; review the CU trend in four weeks before considering F128."]}],"tasks":["Write the executive reply for Grace (Problem, Impact, Recommendation, Ask).","Write the engineering reply for Kenji (Evidence, Options, Risk, with numbers).","Check each against: could the reader act on it without asking a follow-up question?"],"deliverables":[{"id":"exec","t":"Executive version (≤120 words)"},{"id":"eng","t":"Engineering version (≤120 words)"}],"hints":["The executive cares about impact, cost and what you need from her; the engineer cares about evidence, mechanism and risk. Same facts, different order and vocabulary."],"rubric":[{"id":"exec","n":"Executive version","w":40,"good":"No jargon (no CU, throttling, visuals); impact in business terms; a clear recommendation and a specific ask."},{"id":"eng","n":"Engineering version","w":40,"good":"Numbers, mechanism, options with cost and risk, and the monitoring plan."},{"id":"consistent","n":"Consistency","w":20,"good":"Both say the same thing: nothing promised to one audience contradicts the other."}],"retro":["Which version was harder to write, and why?"],"refs":[{"title":"Fabric Capacity Metrics app","url":"https://learn.microsoft.com/en-us/fabric/enterprise/metrics-app"}]},
"s06":{"$schema":"../../schema/scenario.schema.json","id":"s06","slug":"s06-pbip-merge-conflict","type":"sprint","stage":"engineer","order":1,"title":"Two developers, one measure","seo":"Power BI PBIP and TMDL Git merge conflict exercise: resolve a conflict in a semantic model, run Best Practice Analyzer, and write the pull request.","summary":"You and Sam changed the same measure in the shared semantic model on different branches. Git can't merge it. Resolve it without losing either change.","minutes":180,"skills":["deployment","testing","dax","communication"],"prereq":["s05"],"next":"s07","verified":{"date":"2026-10-01","context":"PBIP/TMDL/PBIR project format (Microsoft Learn, 2026-09-23); Tabular Editor 2 BPA","review_after_days":120},"ticket":{"id":"PR-214","kind":"review","priority":"Medium","status":"Blocked: merge conflict","reporter":"sam","opened":"Tue 26 May 2026, 14:40","due":"Release train Thu 28 May","labels":["git","pbip","tmdl","pull-request"]},"story":"The shared model from Sprint 05 now lives in Git as a PBIP project. Every change goes through a pull request reviewed by someone else before Elena deploys it.","impact":"A careless merge silently drops someone's change, or renames a measure that twenty visuals still reference, and nobody notices until a report shows blanks in production. Merging well is what makes team development safe.","messages":[{"from":"sam","to":"you","via":"chat","at":"Tue 26 May, 14:40","body":["Hey, my branch renames Net Sales to Net Revenue (Finance asked for the wording after the consolidation) and adds Net Revenue %. Yours excludes Staff and adds Net Sales LY, right? Git says conflict in _Measures.tmdl. Can you sort it out? I'm in workshops all afternoon. Just take mine if in doubt 😅"]},{"from":"elena","to":"you","via":"pr","at":"Tue 26 May, 15:05","subject":"Review checklist for the release train","body":["- Both changes kept unless one is wrong.\n- No broken references in measures or in report visuals.\n- BPA: no new errors (severity 3); warnings explained.\n- PR description: what changed, why, how it was tested, risk, rollback."]},{"from":"nina","to":"you","via":"email","at":"Tue 26 May, 15:20","subject":"Net Revenue name","body":["Just so you know: in the KPI dictionary \"Net Revenue (ledger)\" is the Finance measure. I asked Sam to rename the order-based one, but I didn't mean to call it plain \"Net Revenue\"! Can we make sure the names don't clash?"]}],"evidence":[{"id":"log","kind":"file","title":"git_log.txt","file":"data/experience/s06/git_log.txt","desc":"Branch graph, the failed merge, and where the report uses the measure."},{"id":"base","kind":"file","title":"base/_Measures.tmdl (common ancestor)","file":"data/experience/s06/base/_Measures.tmdl"},{"id":"ours","kind":"file","title":"ours/_Measures.tmdl (your branch)","file":"data/experience/s06/ours/_Measures.tmdl"},{"id":"theirs","kind":"file","title":"theirs/_Measures.tmdl (Sam's branch)","file":"data/experience/s06/theirs/_Measures.tmdl"},{"id":"conflict","kind":"file","title":"conflicted/_Measures.tmdl (what Git left you)","file":"data/experience/s06/conflicted/_Measures.tmdl"},{"id":"bpa","kind":"file","title":"bpa_results.json (on your branch, before merging)","file":"data/experience/s06/bpa_results.json"}],"tasks":["Work out what each branch changed relative to the common ancestor (a three-way comparison, not two files side by side).","Resolve the conflict so both intentions survive, and so no measure or visual references a name that no longer exists.","Validate: the file must open in Power BI Desktop (or parse in Tabular Editor), every measure must evaluate, and BPA must show no new errors.","Commit with a meaningful message and write the pull request description, including risk and rollback."],"deliverables":[{"id":"res","t":"Resolved _Measures.tmdl"},{"id":"refs","t":"List of every reference you had to update (measures and report visuals)"},{"id":"bpa","t":"BPA result after the merge, with each remaining warning explained"},{"id":"pr","t":"Pull request description","artifact":"pull-request"}],"hints":["Diff base→ours and base→theirs separately. List each change as a sentence (\"ours: Net Sales now excludes Staff\"). The conflict is only where both sentences touch the same lines.","Both branches changed the same measure: one changed its expression, the other its name and format. The resolved measure needs one name, one expression and one format. Then look for everything that still says [Net Sales]: a measure on your branch and three visuals in the report.","Before you pick the new name, read Nina's email and the KPI dictionary from Sprint 05. What should the order-based measure be called so it can never be confused with the ledger one?"],"rubric":[{"id":"correct","n":"Technical correctness","w":30,"good":"Resolved file keeps the Staff exclusion, the LY measure and the % measure, uses one agreed name everywhere, has no conflict markers and evaluates."},{"id":"refs","n":"Dependency awareness","w":20,"good":"Finds and updates every reference: the LY measure, the % measure and the three report visuals (or keeps the old name and explains why)."},{"id":"testing","n":"Testing","w":20,"good":"Opens the project, refreshes, compares values before and after, runs BPA and explains remaining warnings."},{"id":"comm","n":"Pull request and communication","w":20,"good":"PR description says what, why, how tested, risk and rollback; Sam and Nina know the final name."},{"id":"git","n":"Git hygiene","w":10,"good":"Merge commit message is meaningful; no unrelated files (localSettings.json, cache.abf) committed."}],"retro":["Why did Git produce a conflict here when it merged other files automatically?","What working agreement would make this conflict less likely next time?","How do renames interact with reports that reference measures by name?"],"refs":[{"title":"Power BI Desktop projects (PBIP)","url":"https://learn.microsoft.com/en-us/power-bi/developer/projects/projects-overview"},{"title":"Project semantic model folder (TMDL)","url":"https://learn.microsoft.com/en-us/power-bi/developer/projects/projects-dataset"},{"title":"Tabular Model Definition Language (TMDL)","url":"https://learn.microsoft.com/en-us/analysis-services/tmdl/tmdl-overview"}]},
"s07":{"$schema":"../../schema/scenario.schema.json","id":"s07","slug":"s07-test-prod-deployment-failure","type":"sprint","stage":"engineer","order":2,"title":"Test is right, Production is wrong","seo":"Power BI deployment pipeline troubleshooting: after promoting from Test to Production the numbers differ. Diagnose deployment rules, parameters, data source bindings and credentials.","summary":"After Monday's release, Production shows nothing for May and last month's targets, while Test looks perfect. Same model, same report. Find out why.","minutes":180,"skills":["deployment","service","testing","automation"],"prereq":["s06"],"next":"s08","verified":{"date":"2026-10-01","context":"Deployment pipelines and deployment rules (Microsoft Learn, Sept 2026)","review_after_days":120},"ticket":{"id":"INC-2058","kind":"incident","severity":"SEV2","priority":"High","status":"Open","reporter":"jordan","opened":"Wed 3 Jun 2026, 08:47","due":"Today","labels":["deployment","pipeline","production"]},"story":"The release from Sprint 06 was promoted through the deployment pipeline on Monday evening: Development → Test (checked by Nina) → Production.","impact":"Regional managers plan this week's targets from Production. With no May sales and last month's targets they will under-plan, and anyone comparing Production with Test will stop trusting both.","messages":[{"from":"jordan","to":"elena","via":"email","at":"Wed 3 Jun, 08:47","subject":"May is blank??","body":["The sales app shows nothing for May and the targets look like last month's. Nina says the Test version is fine. What happened on Monday?"]},{"from":"elena","to":"you","via":"chat","at":"Wed 3 Jun, 08:55","body":["Sam deployed Test → Prod on Monday at 18:12 and refresh says Completed every day since. Please find out why Prod differs from Test, fix it properly (not by editing Prod by hand) and tell me how we stop it happening again."]},{"from":"kenji","to":"you","via":"chat","at":"Wed 3 Jun, 09:10","body":["Nothing changed on the warehouse side. Prod DW loaded fine last night: max order date is 1 June. Oh, and I still need to drop that load-test copy I restored on the prod server in March, sorry."]}],"evidence":[{"id":"pipe","kind":"file","title":"deployment_pipeline.json","file":"data/experience/s07/deployment_pipeline.json","desc":"Stages, workspaces and deployment rules."},{"id":"params","kind":"file","title":"parameters_by_stage.csv","file":"data/experience/s07/parameters_by_stage.csv","desc":"Parameter values in each stage's semantic model after Monday's deployment."},{"id":"dbs","kind":"file","title":"sql_databases.csv","file":"data/experience/s07/sql_databases.csv"},{"id":"bind","kind":"file","title":"datasource_bindings.csv","file":"data/experience/s07/datasource_bindings.csv","desc":"Gateway and cloud connections bound to each stage's model."},{"id":"refresh","kind":"file","title":"refresh_history_prod.csv","file":"data/experience/s07/refresh_history_prod.csv"},{"id":"compare","kind":"file","title":"stage_comparison.csv","file":"data/experience/s07/stage_comparison.csv","desc":"A few checks Nina ran in Test and Production this morning."}],"tasks":["Explain every difference between Test and Production in stage_comparison.csv, with the piece of configuration that causes it.","Fix Production through the pipeline (rules, bindings, credentials), not by editing the published model by hand.","Verify Production against the warehouse after the fix.","Propose preventive controls: what should a deployment check before and after it runs?"],"deliverables":[{"id":"rca","t":"Root cause: each Test/Prod difference mapped to its cause","artifact":"incident-report"},{"id":"fix","t":"The configuration changes (rules, connection, credential owner)"},{"id":"check","t":"Post-deployment checklist (automatable)","artifact":"deployment-checklist"},{"id":"runbook","t":"Runbook entry: how to diagnose \"Test fine, Prod wrong\" next time","artifact":"runbook"}],"hints":["\"Refresh: Completed\" only says the model loaded data successfully, not that it loaded the right data. Compare row counts and max dates in stage_comparison.csv with sql_databases.csv: which database has exactly those numbers?","Deployment rules only change what they're told to change. Compare the Test and Production rules for the same item. What happens to a parameter that has no rule in the target stage?","Targets come from a different source. Read the Message column in the refresh history and look at whose credential the Production connection uses."],"rubric":[{"id":"invest","n":"Investigation quality","w":25,"good":"Both causes proven with matching numbers (rows and max date equal NorthwindDW_Dev; Targets stale with a warning) rather than guessed."},{"id":"correct","n":"Technical correctness","w":25,"good":"DatabaseName rule added for Production; Targets connection uses a service credential; Prod refreshed and matches the warehouse."},{"id":"prevent","n":"Prevention","w":25,"good":"Rules for every environment-specific parameter; post-deployment checks (row count, max date, connection target) that fail loudly; refresh warnings treated as failures; the stray database dropped."},{"id":"comm","n":"Communication","w":15,"good":"Jordan hears what was wrong, since when, that it's fixed and what to re-check; no jargon."},{"id":"proc","n":"Process","w":10,"good":"Fix goes through the pipeline and is documented in the runbook; nobody edits Production by hand."}],"retro":["Why did every refresh report Completed while the data was wrong?","Which of the two causes would an automated post-deployment test catch, and which needs monitoring?","Who should own the credentials of a production data source?"],"refs":[{"title":"Deployment pipelines overview","url":"https://learn.microsoft.com/en-us/fabric/cicd/deployment-pipelines/intro-to-deployment-pipelines"},{"title":"Create deployment rules","url":"https://learn.microsoft.com/en-us/fabric/cicd/deployment-pipelines/create-rules"},{"title":"Manage data sources for a gateway","url":"https://learn.microsoft.com/en-us/power-bi/connect-data/service-gateway-data-sources"}]},
"d03":{"$schema":"../../schema/scenario.schema.json","id":"d03","slug":"d03-pull-request-review","type":"drill","stage":"engineer","order":3,"title":"Review Sam's pull request","seo":"Power BI code review drill: review a TMDL pull request with calculated columns on a fact table, a bi-directional relationship, duplicate and badly named measures.","summary":"Sam's PR adds margin to the shared model. It's due in today's release train. Review the diff and decide: approve, or request changes?","minutes":45,"skills":["deployment","modeling","dax","performance","communication"],"prereq":["s06"],"ticket":{"id":"PR-231","kind":"review","priority":"Normal","reporter":"sam","opened":"Thu 4 Jun 2026, 11:20","labels":["pull-request","review"]},"impact":"Review is the cheapest place to stop a slow, wrong or confusing change. After it ships, every report built on the shared model inherits the problem.","messages":[{"from":"sam","to":"you","via":"pr","at":"Thu 4 Jun, 11:20","subject":"PR-231: Add margin to the sales model","body":["Jordan needs margin by customer for Monday. Adds Line Margin and a few measures. Tested in Desktop, numbers look right. Can you approve before the 3pm train? 🙏"]}],"evidence":[{"id":"diff","kind":"file","title":"pr-231.diff","file":"data/experience/d03/pr-231.diff","desc":"The full change."},{"id":"rules","kind":"doc","title":"Team modeling standards (excerpt)","body":["- Measures: descriptive names, display folder, description, format string; use DIVIDE.\n- No calculated columns on fact tables over 1M rows unless agreed; push logic upstream.\n- Relationships single direction unless an ADR says otherwise.\n- One measure per concept: no duplicates."]}],"tasks":["Review the diff line by line. Write each comment as you would on GitHub: the line, the problem, why it matters, the suggested change.","Decide approve / request changes, and say what must change before the 3pm train and what can follow later."],"deliverables":[{"id":"rev","t":"Review comments and decision","artifact":"pull-request"}],"hints":["There are six distinct problems in fifteen added lines: two columns, four measures, one relationship. Check each against the team standards.","For each problem ask: is it wrong, slow, confusing or risky? Wrong and risky block the merge; confusing can sometimes be a follow-up."],"rubric":[{"id":"find","n":"Issues found","w":40,"good":"All six issues found: calculated column on the fact, text year column, m1 naming and / operator, duplicate margin measures, hard-coded year, bi-directional relationship (plus missing descriptions)."},{"id":"why","n":"Explanation","w":25,"good":"Each comment says why it matters (performance, correctness, maintainability, ambiguity)."},{"id":"fix","n":"Suggested fixes","w":20,"good":"Concrete alternatives: margin in the source or as a measure with SUMX, DATESYTD or a year filter on DimDate, single direction."},{"id":"tone","n":"Tone and decision","w":15,"good":"Respectful, specific; clear decision with what blocks and what can follow."}],"retro":["Which of these would a Best Practice Analyzer rule catch automatically?","How do you review fast without rubber-stamping?"],"refs":[{"title":"Bi-directional relationship guidance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/relationships-bidirectional-filtering"},{"title":"Avoid converting BLANKs and use DIVIDE","url":"https://learn.microsoft.com/en-us/dax/best-practices/dax-divide-function-operator"}]},
"s09":{"$schema":"../../schema/scenario.schema.json","id":"s09","slug":"s09-fabric-migration-decision","type":"sprint","stage":"architect","order":1,"title":"Should Northwind move to Fabric, and how?","seo":"Microsoft Fabric architecture decision exercise: Import vs DirectQuery vs Direct Lake on OneLake vs Direct Lake on SQL, Lakehouse vs Warehouse, mirroring. Write an architecture decision record under real constraints.","summary":"The Premium capacity is being retired at renewal. Choose a target architecture for the company's models (Import, DirectQuery, Direct Lake, Lakehouse, Warehouse, mirroring) and record the decision as ADR-009.","minutes":300,"skills":["architecture","fabric","performance","governance","communication"],"prereq":["s05","s08"],"next":"s10","verified":{"date":"2026-10-01","context":"Direct Lake overview (2026-09-02), How Direct Lake works (2026-09-09), Mirroring SQL Server (updated 2026-07-06), Premium-to-Fabric migration guidance","review_after_days":90},"ticket":{"id":"ARCH-009","kind":"decision","priority":"High","status":"Open","reporter":"elena","opened":"Mon 6 Jul 2026, 09:00","due":"Architecture board, Thu 23 Jul","labels":["fabric","architecture","direct-lake","adr"]},"story":"The certified model from Sprint 05 now serves 140 people. Refresh takes 74 minutes and is creeping up; the operations dashboard still uses DirectQuery against the warehouse management system, and Sprint 08 showed how fragile the on-premises chain is.","impact":"This decision fixes the platform, cost and skills the BI team will live with for three to five years. Getting it wrong means either an expensive migration that changes nothing for users, or a cheap one that hits a wall in a year.","messages":[{"from":"elena","to":"you","via":"email","at":"Mon 6 Jul, 09:00","subject":"ADR-009: target architecture","body":["Our P1 capacity won't be renewed in December: Microsoft is retiring Premium per-capacity SKUs, and the equivalent is an F64 Fabric capacity. That forces a decision, so let's make a good one.","Please write ADR-009 for the architecture board on the 23rd: options, constraints, trade-offs, your recommendation, consequences, risks and what would make us revisit it. Everything you need is in the folder.","I don't want the most modern option. I want the one this team can run."]},{"from":"kenji","to":"you","via":"chat","at":"Mon 6 Jul, 10:15","body":["If we go Fabric I'd love to stop running nightly ETL into NorthwindDW and Power BI separately. Mirroring could replicate NorthwindDW into OneLake continuously. But nobody here knows Spark, and I'm not learning it by December."]},{"from":"sarah","to":"you","via":"email","at":"Mon 6 Jul, 11:30","subject":"Cost","body":["Whatever you propose: no increase in platform spend next year unless there's a business case I can defend. And Finance's access rules must not get weaker."]},{"from":"jordan","to":"you","via":"chat","at":"Mon 6 Jul, 12:02","body":["Ops says they need everything real time. I need my sales numbers faster than 'tomorrow' too. Can Fabric do real time for everything?"]}],"evidence":[{"id":"estate","kind":"file","title":"current_estate.csv","file":"data/experience/s09/current_estate.csv","desc":"Today's main models: storage mode, size, refresh, consumers, latency needed."},{"id":"cons","kind":"file","title":"constraints.csv","file":"data/experience/s09/constraints.csv"},{"id":"load","kind":"file","title":"refresh_and_load.csv","file":"data/experience/s09/refresh_and_load.csv","desc":"Refresh duration and source load over the last four weeks."},{"id":"modes","kind":"table","title":"Storage options in Fabric (summary checked 1 Oct 2026)","cols":["Option","How data reaches the model","Fallback","Notes"],"rows":[["Import","Copied at refresh","n/a","Power Query in the model; works on any licence"],["DirectQuery","Query sent to the source each time","n/a","Load on the source; latency = source"],["Direct Lake on OneLake","Delta tables in OneLake loaded on demand; refresh = framing","Never: errors instead","Recommended for new models; can combine Fabric sources and Import tables; no non-materialised SQL views; capacity only"],["Direct Lake on SQL endpoint","Same, discovered through one SQL analytics endpoint","Falls back to DirectQuery (views, SQL RLS/OLS, guardrails)","Single source; can't mix with DirectQuery/Dual tables in one model"],["Mirroring (SQL Server 2016–2025)","Continuous replication into OneLake (CDC through a gateway)","n/a","Replication compute free; read-only copy with a SQL analytics endpoint"]]}],"tasks":["Frame the decision: what is actually forced (and by when), and what is optional?","List the constraints and the real latency needs per workload. Challenge \"real time for everything\".","Compare at least three options with pros, cons, costs and risks, against the constraints.","Record your decision (Your work → Decision) and write ADR-009.","Explain the recommendation to the CFO in five sentences and to Kenji in technical terms."],"deliverables":[{"id":"adr","t":"ADR-009: context, constraints, options, recommendation, consequences, risks, revisit trigger","artifact":"adr"},{"id":"lat","t":"Latency and workload table: what each consumer really needs"},{"id":"plan","t":"Phased migration plan with a rollback at each phase","artifact":"release-notes"},{"id":"exec","t":"Five-sentence recommendation for the CFO"}],"decision":{"adr":"ADR-009","title":"Target analytics architecture for 2027","question":"Which option do you recommend to the architecture board?","options":[{"id":"a","t":"Lift and shift: same Import and DirectQuery models on an F64 capacity","d":"Lowest effort and risk. Nothing changes for users or the team."},{"id":"b","t":"Phased: lift to F64 first, then mirror NorthwindDW into OneLake, build gold tables in a Fabric Warehouse (T-SQL) and move Sales to Direct Lake on OneLake; Finance stays Import","d":"Two steps. Uses the team's SQL skills, removes the long Sales refresh and the WMS DirectQuery load."},{"id":"c","t":"Big bang: Lakehouse with Spark notebooks and a medallion architecture; every model to Direct Lake by December","d":"The most modern stack, all at once."},{"id":"d","t":"DirectQuery everywhere against the on-premises SQL Servers for freshness; no Fabric items","d":"Real time for everyone, no refresh at all."}]},"hints":["Separate the forced decision (P1 is retired in December, so something must run on F capacity) from the optional one (how far to go beyond lift and shift, and when).","Rewrite each latency requirement as a number with an owner. Only one workload needs minutes; the rest are hours or daily. Which option serves that one without putting load back on the WMS?","Score the options against the team (no Spark), the budget (no increase without a case), security (Finance must not weaken) and Direct Lake's rules (views, SQL RLS and fallback). The recommendation can be phased."],"rubric":[{"id":"frame","n":"Problem framing","w":15,"good":"Separates the forced capacity change from the optional modernisation, with dates."},{"id":"cons","n":"Constraints identified","w":15,"good":"Skills, budget, security, latency per workload, source load and growth are all named and quantified."},{"id":"trade","n":"Trade-off analysis","w":25,"good":"At least three options compared honestly, including Direct Lake on OneLake vs on SQL endpoint, mirroring, and what each does to cost, skills, security and latency."},{"id":"tech","n":"Technical viability","w":20,"good":"The design respects current product rules: no views in Direct Lake on OneLake, RLS in the semantic model rather than SQL, guardrails, gateway needs for mirroring."},{"id":"risk","n":"Risk analysis","w":10,"good":"Risks have mitigations and a revisit trigger (e.g. refresh > 90 min, CU usage > 80%)."},{"id":"rec","n":"Recommendation quality","w":15,"good":"One clear recommendation, phased, with a rollback per phase, explained to the CFO without jargon."}],"retro":["Which constraint drove your decision most? Would a different team have chosen differently?","What evidence would make you revisit ADR-009 in a year?","How did you handle \"real time for everything\"?"],"refs":[{"title":"Direct Lake overview","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/direct-lake-overview"},{"title":"Mirroring SQL Server in Fabric","url":"https://learn.microsoft.com/en-us/fabric/mirroring/sql-server"},{"title":"Power BI Premium to Fabric migration overview","url":"https://learn.microsoft.com/en-us/power-bi/support/premium-migration-overview"},{"title":"Fabric decision guide: choose a data store","url":"https://learn.microsoft.com/en-us/fabric/fundamentals/decision-guide-data-store"}]},
"s10":{"$schema":"../../schema/scenario.schema.json","id":"s10","slug":"s10-bi-architecture-review","type":"sprint","stage":"architect","order":2,"title":"Architecture review: 80 reports, 19 models, no owner","seo":"Power BI governance and architecture review exercise: assess a messy tenant (reports, semantic models, workspaces), design the target architecture, governance model, consolidation plan and executive recommendation.","summary":"The new CEO-sponsored data programme starts with a question: what do we actually have, and what should it look like in a year? You lead the review.","minutes":360,"skills":["architecture","governance","security","communication","service"],"prereq":["s09"],"ticket":{"id":"ARCH-012","kind":"review","priority":"High","status":"Open","reporter":"grace","opened":"Mon 14 Sep 2026, 09:00","due":"Leadership offsite, Fri 9 Oct","labels":["governance","architecture","consolidation","roadmap"]},"story":"You are now leading BI architecture at Northwind. The shared revenue model (Sprint 05), the deployment checks (Sprint 07), the incident process (Sprint 08) and ADR-009 (Sprint 09) all exist, but only for the parts of the estate the BI team touches.","impact":"Every unmanaged copy of a model is a possible wrong number, a possible data leak and a refresh that costs capacity. The offsite will decide the data programme's budget; a vague review gets a vague budget.","messages":[{"from":"grace","to":"you","via":"email","at":"Mon 14 Sep, 09:00","subject":"What do we have?","body":["I keep hearing we have \"hundreds\" of reports and nobody knows which to trust. Before the offsite I want a short, honest picture of where we are, where we should be in a year, and what it takes to get there.","One page for the leadership team, the detail behind it for Elena. Grace"]},{"from":"elena","to":"you","via":"chat","at":"Mon 14 Sep, 09:30","body":["I exported the tenant inventory: workspaces, semantic models, reports with 90-day views. It's messy. Don't propose deleting things you haven't checked; people get very upset about \"their\" report.","And please don't produce a 40-page governance framework nobody reads."]},{"from":"ava","to":"you","via":"email","at":"Mon 14 Sep, 11:10","subject":"Ownership","body":["From a compliance point of view my main concern is items with personal or financial data that have no named owner. Please flag those."]}],"earlier":[{"scenario":"s09","intro":"In ADR-009 you chose the target platform. This review has to be consistent with it.","consequences":{"a":"You kept the existing models on F64 as they are. The review must therefore tackle duplication model by model: no platform change will consolidate anything for you.","b":"Phase 2 of your plan creates one gold layer in OneLake. Use it: consolidation targets for Sales, Ops and Customer data can all land on the mirrored and gold tables instead of each model loading its own copy.","c":"Your big-bang Lakehouse plan is behind schedule and the team is learning Spark. Be realistic about how much consolidation the same team can do this year.","d":"DirectQuery everywhere has increased load on every source system, and the DBAs now want to restrict BI access. Address this before adding more models.","default":"Most architecture boards choose the phased option (lift to F64, then a gold layer in OneLake). If you haven't recorded ADR-009, assume that."},"none":"You haven't recorded ADR-009 yet (Sprint 09)."}],"evidence":[{"id":"ws","kind":"file","title":"workspaces.csv","file":"data/experience/s10/workspaces.csv"},{"id":"sm","kind":"file","title":"semantic_models.csv","file":"data/experience/s10/semantic_models.csv","desc":"Owner, endorsement, revenue measure name, customer table name, RLS and last refresh status."},{"id":"rp","kind":"file","title":"reports.csv","file":"data/experience/s10/reports.csv","desc":"Every report with its model and views in the last 90 days."},{"id":"maturity","kind":"doc","title":"What already exists from earlier work","body":["- Certified shared sales model with a KPI dictionary (BI-1103).\n- Deployment pipeline with post-deployment checks for the BI team's workspaces (INC-2058).\n- Incident severity guide and on-call alerts for certified models (INC-2071).\n- ADR-009 on the target platform."]}],"tasks":["Assess the current state with numbers: duplication, ownership, endorsement, usage, refresh health, revenue and customer definitions.","Design the target: workspace strategy, model consolidation, endorsement and ownership, security, and how it fits ADR-009.","Define a light governance model that people will actually follow.","Plan a 12-month roadmap with phases, owners and risks. Nothing is deleted without checking dependencies and telling owners.","Write the one-page executive recommendation for the offsite."],"deliverables":[{"id":"cur","t":"Current-state assessment with numbers"},{"id":"tgt","t":"Target architecture and workspace strategy","artifact":"adr"},{"id":"gov","t":"Governance model: roles, endorsement criteria, ownership rules","artifact":"ownership-matrix"},{"id":"cons","t":"Consolidation and retirement plan","artifact":"release-notes"},{"id":"road","t":"12-month roadmap with risks"},{"id":"exec","t":"One-page executive recommendation"}],"hints":["Count before you judge: reports with zero views in 90 days, models without an owner, how many different names Revenue has, how many different customer tables exist, how concentrated usage is.","Usage is very concentrated: a few models serve most viewers. Consolidation should start from what people use, not from what is messy.","Governance that works is short: a few roles, a few rules, and making the certified path the easiest one. Retirement needs a process (owner contact, read-only period, archive), not a delete button."],"rubric":[{"id":"frame","n":"Problem framing","w":15,"good":"States the core problem (no ownership and duplicated definitions) rather than listing symptoms."},{"id":"cons","n":"Evidence and constraints","w":15,"good":"Current state quantified from the inventory; personal and financial data without owners flagged."},{"id":"trade","n":"Trade-off analysis","w":25,"good":"Central vs federated workspaces, consolidation vs leave alone, strict vs light governance, weighed honestly."},{"id":"tech","n":"Technical viability","w":20,"good":"Target fits ADR-009 and current platform features (endorsement, domains, lineage, usage metrics, deployment pipelines)."},{"id":"risk","n":"Risk analysis","w":10,"good":"Change resistance, hidden dependencies, capacity and team capacity are addressed with mitigations."},{"id":"rec","n":"Recommendation quality","w":15,"good":"One page, three decisions for leadership, a budget ask and a measurable target for 12 months."}],"retro":["Which number from the inventory will persuade the leadership team most, and why?","Where did you choose federation over central control, and what would make you change that?","What is the first thing you'd do on Monday after the offsite?"],"refs":[{"title":"Power BI implementation planning: governance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/fabric-adoption-roadmap-governance"},{"title":"Fabric domains","url":"https://learn.microsoft.com/en-us/fabric/governance/domains"},{"title":"Endorsement overview","url":"https://learn.microsoft.com/en-us/fabric/governance/endorsement-overview"},{"title":"Lineage in Fabric","url":"https://learn.microsoft.com/en-us/fabric/governance/lineage"}]},
"d07":{"$schema":"../../schema/scenario.schema.json","id":"d07","slug":"d07-governance-maturity","type":"drill","stage":"architect","order":3,"title":"Governance maturity assessment","seo":"Power BI and Fabric governance maturity self-assessment: ownership, endorsement, security, lifecycle, monitoring and data quality, with next steps per dimension.","summary":"Assess Northwind's BI governance (or your own organisation's) on six dimensions and get the next step for each.","minutes":30,"skills":["governance","architecture","security"],"prereq":["s10"],"ticket":{"id":"GOV-050","kind":"review","priority":"Normal","reporter":"elena","opened":"Tue 22 Sep 2026, 10:00","labels":["governance","maturity"]},"impact":"A maturity assessment turns \"we should govern better\" into a short list of next steps the organisation can actually take this quarter.","messages":[{"from":"elena","to":"you","via":"chat","at":"Tue 22 Sep, 10:00","body":["Before the offsite, score where we are on each governance dimension. Be honest: the point is the next step, not the score. Use your own company instead if you prefer."]}],"evidence":[{"id":"s10","kind":"doc","title":"From the architecture review (Sprint 10)","body":["- 6 of 19 models without owner; 31 of 80 reports unused for 90 days.\n- 2 certified models; 3 workspaces with deployment pipelines.\n- Incident process and on-call alerts exist for certified models only."]}],"interactive":{"type":"assessment","title":"Score each dimension from 1 to 5","intro":"Choose the description that is true today, not the one you're planning.","labels":["Initial","Repeatable","Defined","Managed","Optimised"],"dims":[{"n":"Ownership","q":"Who is responsible for reports and models?","levels":["Nobody knows who owns most items.","Owners are known informally for important items.","Every item in production has a named owner in metadata.","Owners review their items periodically; orphaned items are flagged automatically.","Ownership transfers are part of joiner/mover/leaver processes."],"next":["Run an ownership drive for everything used in the last 90 days.","Record owners in metadata (contact list) and require it to publish.","Add a quarterly owner review using usage and lineage.","Automate orphan detection with the admin APIs.","Keep it: audit ownership changes in HR processes."]},{"n":"Definitions and endorsement","q":"How are company KPIs defined and served?","levels":["Each report defines its own KPIs.","A few shared models exist; KPIs still duplicated.","Certified models serve company KPIs; a KPI dictionary exists.","Certification has criteria and owners; non-certified KPI copies are tracked.","Most consumption runs on certified models; definitions change through a governed process."],"next":["Pick the top 5 KPIs and write them down with owners.","Certify one shared model for those KPIs.","Publish endorsement criteria and a certification process.","Report certified share of views and chase the copies.","Measure and review definition changes quarterly."]},{"n":"Security","q":"How is data access controlled and tested?","levels":["Access by sharing links; no RLS testing.","Workspace roles and some RLS.","RLS/OLS in models, groups not individuals, sensitivity labels on sensitive items.","Security test matrices run on every release; access reviewed quarterly.","Least privilege enforced by policy; access anomalies monitored."],"next":["Move to group-based access and remove broad sharing links.","Add RLS/OLS to sensitive models and label them.","Create a test matrix per sensitive model and run it on release.","Quarterly access reviews with owners.","Monitor activity logs for unusual access."]},{"n":"Lifecycle","q":"How do changes reach production?","levels":["People publish from Desktop to production.","Separate test workspace for some items.","Dev/Test/Prod with deployment pipelines for certified content; PBIP in Git.","Pull requests, automated checks (BPA, tests) and rollback for all production content.","Release metrics tracked; failure rate and lead time improve."],"next":["Create Dev/Test/Prod for the most-used models.","Put certified models in Git as PBIP with pipelines.","Add PR review and automated checks.","Track change failure rate and time to restore.","Keep improving the release process."]},{"n":"Monitoring","q":"How do you know something is wrong?","levels":["Users tell us.","Refresh failure emails to individual owners.","Alerts to a team for certified models; capacity metrics checked.","SLOs for refresh and performance; usage reviewed monthly.","Proactive: trends predict problems before users see them."],"next":["Route failure notifications to a team mailbox.","Define severity levels and on-call for certified models.","Set refresh and performance SLOs; review monthly.","Trend capacity and refresh duration to plan ahead.","Keep it and share the learning."]},{"n":"Data quality","q":"How are numbers validated?","levels":["Not validated.","Spot checks before big meetings.","Reconciliations and data tests for certified models.","Automated tests in the pipeline; contracts with source teams.","Quality metrics published; issues fixed at the source."],"next":["Write a reconciliation for the top KPIs.","Automate data tests (row counts, uniqueness, totals).","Agree data contracts with source owners.","Publish quality metrics next to the KPIs.","Keep it."]}]},"tasks":["Score each dimension honestly.","Pick the two next steps with the best value for effort, and say who would own them."],"deliverables":[{"id":"score","t":"Maturity scores with evidence"},{"id":"next","t":"Top two next steps with owners and dates","artifact":"ownership-matrix"}],"hints":["Score what's true for most of the estate, not for the BI team's showcase model."],"rubric":[{"id":"honest","n":"Evidence-based scoring","w":40,"good":"Each score is backed by a fact from the inventory or experience, not by aspiration."},{"id":"prio","n":"Prioritisation","w":40,"good":"Next steps chosen for value and effort; owners named."},{"id":"comm","n":"Communication","w":20,"good":"Can be presented in two minutes."}],"retro":["Which dimension surprised you most?"],"refs":[{"title":"Power BI implementation planning: governance","url":"https://learn.microsoft.com/en-us/power-bi/guidance/fabric-adoption-roadmap-governance"}]}
};
